CREATE TRIGGER kids_school_assertion_identity_source_v2 BEFORE INSERT ON kids_school_assertions
WHEN ((SELECT COUNT(*) FROM kids_school_assertions WHERE owner_user_id=NEW.owner_user_id AND workspace_id=NEW.workspace_id)>=5000 AND NOT EXISTS(SELECT 1 FROM kids_school_assertions a WHERE a.owner_user_id=NEW.owner_user_id AND a.workspace_id=NEW.workspace_id AND a.source_key=NEW.source_key AND a.context_id=NEW.context_id AND a.child_id=NEW.child_id))
 OR NOT EXISTS(SELECT 1 FROM kids_source_records s JOIN kids_state k ON k.user_id=s.owner_user_id AND k.id=s.workspace_id JOIN kids_operation_receipts r ON r.owner_user_id=k.user_id AND r.workspace_id=k.id AND r.committed_revision=k.revision JOIN kids_hosted_batches b ON b.id=json_extract(r.source_authority,'$.batchId') WHERE s.owner_user_id=NEW.owner_user_id AND s.workspace_id=NEW.workspace_id AND s.source_key=NEW.source_key AND s.fingerprint=NEW.fingerprint AND b.status='saved' AND json_extract(r.source_authority,'$.kind')='hosted-source-batch-v1' AND b.owner_user_id=k.user_id AND b.workspace_id=k.id AND (EXISTS(SELECT 1 FROM kids_hosted_batch_members m WHERE m.batch_id=b.id AND EXISTS(SELECT 1 FROM kids_source_records identity_source WHERE identity_source.owner_user_id=NEW.owner_user_id AND identity_source.workspace_id=NEW.workspace_id AND identity_source.source_key=NEW.source_key AND identity_source.message_id=m.message_id AND b.chat_id=identity_source.chat_id AND ((identity_source.chat_id=m.chat_id AND NOT EXISTS(SELECT 1 FROM kids_source_connections identity_connection WHERE identity_connection.owner_user_id=NEW.owner_user_id AND identity_connection.workspace_id=NEW.workspace_id)) OR EXISTS(SELECT 1 FROM kids_chat_sources identity_chat WHERE identity_chat.owner_user_id=NEW.owner_user_id AND identity_chat.workspace_id=NEW.workspace_id AND identity_chat.app_chat_id=identity_source.chat_id AND identity_chat.binding_id=b.binding_id AND identity_chat.provider_chat_id=m.chat_id))) AND m.fingerprint=NEW.fingerprint) OR EXISTS(SELECT 1 FROM kids_hosted_history_batch_members m WHERE m.batch_id=b.id AND EXISTS(SELECT 1 FROM kids_source_records identity_source WHERE identity_source.owner_user_id=NEW.owner_user_id AND identity_source.workspace_id=NEW.workspace_id AND identity_source.source_key=NEW.source_key AND identity_source.message_id=m.message_id AND b.chat_id=identity_source.chat_id AND ((identity_source.chat_id=m.chat_id AND NOT EXISTS(SELECT 1 FROM kids_source_connections identity_connection WHERE identity_connection.owner_user_id=NEW.owner_user_id AND identity_connection.workspace_id=NEW.workspace_id)) OR EXISTS(SELECT 1 FROM kids_chat_sources identity_chat WHERE identity_chat.owner_user_id=NEW.owner_user_id AND identity_chat.workspace_id=NEW.workspace_id AND identity_chat.app_chat_id=identity_source.chat_id AND identity_chat.binding_id=b.binding_id AND identity_chat.provider_chat_id=m.chat_id))) AND m.fingerprint=NEW.fingerprint)) AND EXISTS(SELECT 1 FROM kids_source_links l WHERE l.owner_user_id=k.user_id AND l.workspace_id=k.id AND l.context_id=NEW.context_id AND l.source_key=NEW.source_key AND l.task_id='') AND EXISTS(SELECT 1 FROM json_each(k.document,'$.contexts') c WHERE json_extract(c.value,'$.id')=NEW.context_id AND EXISTS(SELECT 1 FROM json_each(c.value,'$.childIds') p WHERE p.value=NEW.child_id)))
BEGIN SELECT RAISE(ABORT,'KIDS_SCHOOL_ASSERTION_IDENTITY'); END;
