 ((identity_source.chat_id=m.chat_id AND NOT EXISTS(SELECT 1 FROM kids_source_connections identity_connection WHERE identity_connection.owner_user_id=NEW.owner_user_id AND identity_connection.workspace_id=NEW.workspace_id)) OR EXISTS(SELECT 1 FROM kids_chat_sources identity_chat WHERE identity_chat.owner_user_id=NEW.owner_user_id AND identity_chat.workspace_id=NEW.workspace_id AND identity_chat.app_chat_id=identity_source.chat_id AND identity_chat.binding_id=b.binding_id AND identity_chat.provider_chat_id=m.chat_id))) AND m.fingerprint=NEW.fingerprint)))
